B.bYH=new A.e("\u1780\u17b6\u179a\u1793\u17c1\u179f\u17b6\u1791\u17a0\u17bd\u179f\u1780\u1798\u17d2\u179a\u17b7\u178f","Catching fish from rivers or oceans faster than they can naturally reproduce.","","",!1)
B.bTp=new A.e("\u1780\u17c6\u178e\u17be\u1793\u1794\u17d2\u179a\u1787\u17b6\u1787\u1793\u17a0\u17bd\u179f\u1794\u17d2\u179a\u1798\u17b6\u178e","A condition in which too many people live in one area for the available space and resources.","","",!1)
B.bSj=new A.e("\u1780\u17b6\u179a\u1794\u17c6\u1796\u17bb\u179b\u1781\u17d2\u1799\u179b\u17cb","Harmful smoke, dust, and gases released into the air by factories and vehicles.","","",!1)
B.c0I=new A.e("\u1780\u17b6\u179a\u1794\u17c6\u1796\u17bb\u179b\u1791\u17b9\u1780","The contamination of rivers, lakes, and seas with rubbish, chemicals, or waste.","","",!1)
B.c_m=new A.e("\u179f\u17c6\u179a\u17b6\u1798","Waste material or unwanted items that people throw away.","","",!1)
B.bU_=new A.e("\u1796\u17d2\u179a\u17bd\u1799\u1794\u17b6\u179a\u1798\u17d2\u1797","Feeling anxious or uneasy because you keep thinking about a problem.","","",!1)
B.bWZ=new A.e("\u178f\u17b6\u1793\u178f\u17b9\u1784\u1785\u17b7\u178f\u17d2\u178f","Feeling annoyed or upset because you cannot achieve what you want.","","",!1)
B.bUP=new A.e("\u1782\u17bd\u179a\u17b1\u17d2\u1799\u1797\u17d0\u1799\u1781\u17d2\u179b\u17b6\u1785","Causing people to feel scared or alarmed.","","",!1)
B.c1I=new A.e("\u178a\u17c2\u179b\u1792\u17d2\u179c\u17be\u17b1\u17d2\u1799\u17a0\u178f\u17cb\u1793\u17bf\u1799","Using up your energy and making you want to rest or sleep.","","",!1)
B.c1t=new A.e("\u178a\u17c2\u179b\u1792\u17d2\u179c\u17be\u17b1\u17d2\u1799\u179f\u17c4\u1780\u179f\u17c5","Making you feel very sad, gloomy, and without hope.","","",!1)
B.bRd=new A.e("\u1798\u17b7\u1793\u1794\u17c9\u17c7\u1796\u17b6\u179b\u17cb\u178a\u179b\u17cb\u1794\u179a\u17b7\u179f\u17d2\u1790\u17b6\u1793","Designed or done in a way that does not harm nature or the environment.","","",!1)
B.bSb=new A.e("\u178a\u17c2\u179b\u17a2\u17b6\u1785\u1794\u17d2\u179a\u17be\u1794\u17d2\u179a\u17b6\u179f\u17cb\u17a1\u17be\u1784\u179c\u17b7\u1789","Able to be washed or kept and used many times instead of thrown away.","","",!1)
B.bR_=new A.e("\u1780\u17c2\u1785\u17d2\u1793\u17c3\u17a1\u17be\u1784\u179c\u17b7\u1789","To process used materials like glass, paper, and plastic into new useful products.","","",!1)
B.bSq=new A.e("\u1791\u17b7\u179c\u17b6\u1797\u1796\u1795\u17c2\u1793\u178a\u17b8","An annual international day on 22 April dedicated to protecting the environment.","","",!1)
B.bYa=new A.e("\u1798\u17c9\u17c4\u1784\u1797\u1796\u1795\u17c2\u1793\u178a\u17b8","A global event on the last Saturday of March when people switch off lights for one hour to save energy.","","",!1)
B.bS0=new A.e("\u17a2\u17d2\u1793\u1780\u17a2\u1797\u17b7\u179a\u1780\u17d2\u179f\u1794\u179a\u17b7\u179f\u17d2\u1790\u17b6\u1793","A person who actively works to care for and protect the natural environment.","","",!1)
B.bU5=new A.e("\u178a\u17b6\u17c6\u178a\u17be\u1798\u1788\u17be","To put young trees into the soil to help forests grow and clean the air.","","",!1)
B.c0g=new A.e("\u1782\u17bd\u179a\u17b1\u17d2\u1799\u179f\u1794\u17d2\u1794\u17b6\u1799\u179a\u17b8\u1780\u179a\u17b6\u1799","Fun, amusing, and enjoyable to watch or take part in.","","",!1)
B.bWs=new A.e("\u178a\u17c2\u179b\u1794\u17c6\u1795\u17bb\u179f\u1782\u17c6\u1793\u17b7\u178f","Filling people with enthusiasm and the desire to do something good.","","",!1)
B.bZn=new A.e("\u1797\u17d2\u1789\u17b6\u1780\u17cb\u1795\u17d2\u17a2\u17be\u179b\u1799\u17c9\u17b6\u1784\u1781\u17d2\u179b\u17b6\u17c6\u1784","Feeling great surprise and wonder at something impressive.","","",!1)
B.bR2=new A.e("\u1787\u1780\u17cb\u1785\u17b7\u178f\u17d2\u178f\u1781\u17d2\u179b\u17b6\u17c6\u1784","Feeling extremely interested and curious about something.","","",!1)
B.bR5=new A.e("\u17a2\u179f\u17d2\u1785\u17b6\u179a\u17d2\u1799","Very surprising in a wonderful and impressive way.","","",!1)
B.bS7=new A.e("\u1798\u17b6\u1793\u1780\u1798\u17d2\u179b\u17b6\u17c6\u1784\u1785\u17b7\u178f\u17d2\u178f","Feeling hopeful and supported by others to keep trying.","","",!1)
B.c2h=new A.e("\u1782\u17d2\u179a\u17c4\u17c7\u1798\u17a0\u1793\u17d2\u178f\u179a\u17b6\u1799\u1792\u1798\u17d2\u1798\u1787\u17b6\u178f\u17b7","A sudden, dangerous event in nature such as a flood, storm, or earthquake.","","",!1)
B.c_0=new A.e("\u1797\u17d2\u179b\u17c0\u1784\u1792\u17d2\u179b\u17b6\u1780\u17cb\u1781\u17d2\u179b\u17b6\u17c6\u1784","A large amount of rain falling quickly over an area.","","",!1)
